const cfg  = $('Ajustes y cupo').first().json.cfg;
const lead = $input.first().json;
const toque = Number(lead.toques) + 1;   // el que estamos por enviar
const ultimo = toque >= Number(cfg.max_toques || 3);

const contexto = {
  negocio: lead.negocio, contacto: lead.nombre, rubro: lead.rubro,
  ciudad: lead.ciudad, sitio_web: lead.sitio_web || '(no tiene página)',
  observacion: lead.observacion,
  numero_de_toque: toque,
  es_el_ultimo_mensaje: ultimo,
  dias_desde_el_ultimo_contacto: lead.ultimo_contacto_en
    ? Math.round((Date.now() - new Date(lead.ultimo_contacto_en)) / 86400000)
    : null,
};

const previos = (Array.isArray(lead.historial) ? lead.historial : [])
  .map((m) => (m.role === 'assistant' ? 'YA ENVIADO: ' : 'ÉL DIJO: ') + m.content)
  .join(String.fromCharCode(10));

const peticion = {
  model: cfg.modelo || 'claude-opus-5',
  max_tokens: 8000,
  output_config: {
    effort: cfg.esfuerzo_apertura || 'low',
    format: { type: 'json_schema', schema: {"type": "object", "properties": {"mensaje": {"type": "string", "description": "El mensaje tal cual se envía por WhatsApp."}, "gancho": {"type": "string", "description": "En 6 palabras, el dato concreto del negocio que usaste."}}, "required": ["mensaje", "gancho"], "additionalProperties": false} },
  },
  system: [{
    type: 'text',
    text: cfg.ficha_comercial + String.fromCharCode(10, 10) + cfg.prompt_seguimiento,
    cache_control: { type: 'ephemeral' },
  }],
  messages: [{
    role: 'user',
    content: 'Ficha del negocio:' + String.fromCharCode(10)
           + JSON.stringify(contexto, null, 2)
           + String.fromCharCode(10, 10) + 'Mensajes anteriores:' + String.fromCharCode(10)
           + (previos || '(ninguno)'),
  }],
};

return [{ json: { peticion, lead_id: lead.id, telefono: lead.telefono, toque, ultimo } }];

// WhatsApp no es markdown, y un mensaje en frío con enlaces se va a spam.
function limpiar(txt, maxLargo) {
  let t = String(txt || '')
    .replace(/\*\*(.+?)\*\*/g, '$1')     // **negrita**
    .replace(/^[-*•]\s+/gm, '')            // viñetas
    .replace(/^#{1,6}\s+/gm, '')           // títulos
    .replace(/\[(.+?)\]\(.+?\)/g, '$1')  // [texto](url)
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]+/g, ' ')
    .trim();
  if (t.length > maxLargo) {
    // Cortar en la última frase completa que quepa, no a mitad de palabra.
    const corte = t.slice(0, maxLargo);
    const fin = Math.max(corte.lastIndexOf('. '), corte.lastIndexOf('? '), corte.lastIndexOf('\n'));
    t = (fin > maxLargo * 0.5 ? corte.slice(0, fin + 1) : corte).trim();
  }
  return t;
}

// La respuesta puede traer bloques de razonamiento antes del texto.
function textoDelModelo(respuesta) {
  if (respuesta?.stop_reason === 'refusal') {
    throw new Error('El modelo declinó la petición. Revisa el prompt en ajustes.');
  }
  const bloque = (respuesta?.content || []).find((b) => b.type === 'text' && b.text);
  if (!bloque) {
    throw new Error('Respuesta sin texto: ' + JSON.stringify(respuesta).slice(0, 400));
  }
  return bloque.text;
}


// Literal SQL seguro. Duplicar la comilla simple es lo mismo que hace
// quote_literal() en Postgres, y con standard_conforming_strings=on (por
// defecto) no hay ninguna otra secuencia de escape que valga.
const lit = (v) => (v === null || v === undefined || v === '')
  ? 'null'
  : "'" + String(v).replace(/'/g, "''") + "'";

            const previo = $('Armar seguimiento').first().json;
            const datos  = JSON.parse(textoDelModelo($input.first().json));

            let mensaje = limpiar(datos.mensaje, 340)
              .replace(/https?:\/\/\S+/g, '')
              .replace(/ {2,}/g, ' ')
              .trim();

            if (mensaje.length < 20) {
              throw new Error('Seguimiento demasiado corto, no se envía: ' + mensaje);
            }

            return [{ json: {
              mensaje,
              mensaje_sql: lit(mensaje),
              etapa: 'seguimiento_' + previo.toque,
              lead_id: previo.lead_id,
              telefono: previo.telefono,
              delay_ms: Math.min(50, Math.max(20, mensaje.length / 3)) * 100,
            } }];

